import Foundation

extension SeniorsGuides {
    static let everydaySections: [DirectoryGuideSection] = [
        .init("home-safety", "house", "Зробіть житло безпечнішим", "Die Wohnung sicherer machen",
              "Пройдіть звичний шлях від ліжка до туалету й виходу: приберіть незакріплені килими та дроти, забезпечте світло вночі, перевірте поручні у ванній. Якщо вже були падіння чи змінилася хода, повідомте сімейного лікаря; причину потрібно з’ясувати, а не лише прибрати перешкоди. Перед монтажем у найманому житлі погодьте зміни з орендодавцем.",
              "Gehen Sie den Weg vom Bett zu WC und Ausgang ab: lose Teppiche und Kabel entfernen, nachts für Licht sorgen und Haltegriffe im Bad prüfen. Nach Stürzen oder bei verändertem Gangbild die Hausärztin oder den Hausarzt informieren; die Ursache gehört abgeklärt. Umbauten in einer Mietwohnung vorher mit der Vermietung abstimmen.", source: homeSafety),
        .init("home-alarm", "bell", "Покличте допомогу, навіть якщо телефон недосяжний", "Hilfe rufen, wenn das Telefon nicht erreichbar ist",
              "Для людини, яка живе сама або може впасти, порівняйте Hausnotruf: як носити кнопку, чи працює вона поза квартирою, хто відповідає, як потраплять усередину, що відбувається при відключенні зв’язку та скільки коштують установка й щомісячна послуга. Узгодьте з довіреною особою запасний ключ і регулярну перевірку контакту. У невідкладній ситуації телефонуйте 144 або 112.",
              "Für alleinlebende oder sturzgefährdete Personen Hausnotruf-Angebote vergleichen: Trageweise des Knopfs, Reichweite außerhalb der Wohnung, Leitstelle, Wohnungszugang, Ausfall des Anschlusses sowie Anschluss- und Monatskosten. Ersatzschlüssel und regelmäßigen Kontakt mit einer Vertrauensperson vereinbaren. Im akuten Notfall 144 oder 112 wählen.", source: alarm),
        .init("medication", "pills", "Перевірте всі ліки разом", "Alle Arzneimittel gemeinsam prüfen",
              "Зберіть для прийому в лікаря перелік усіх рецептних і безрецептурних ліків, добавок, доз та часу прийому; візьміть також виписки від інших фахівців. Запитайте про взаємодії, дублікати діючих речовин, запаморочення та зрозумілий план прийому. Не припиняйте й не змінюйте дозу самостійно. Якщо зір або пам’ять заважають прийому, попросіть аптеку про читабельний план чи придатне пакування.",
              "Zum Arzttermin eine Liste aller verschriebenen und frei gekauften Arzneimittel, Ergänzungsmittel, Dosierungen und Einnahmezeiten sowie Befunde anderer Fachstellen mitnehmen. Nach Wechselwirkungen, doppelten Wirkstoffen, Schwindel und einem verständlichen Einnahmeplan fragen. Dosen nicht selbst ändern oder absetzen. Bei Seh- oder Gedächtnisproblemen die Apotheke nach einem lesbaren Plan oder geeigneter Verpackung fragen.", source: medicines),
        .init("food-drink", "fork.knife", "Помічайте втрату ваги й труднощі з їжею", "Gewichtsverlust und Essprobleme erkennen",
              "Якщо людина ненавмисно худне, мало їсть чи п’є, має біль під час жування або ковтання, запишіть коли це почалося й зверніться до сімейного лікаря. Попросіть перевірити можливі причини, зокрема ліки, зуби та ковтання; за потреби — направлення до дієтолога. Не починайте висококалорійні напої чи добавки навмання: їх добирають за станом здоров’я.",
              "Bei unbeabsichtigtem Gewichtsverlust, wenig Essen oder Trinken sowie Kau- oder Schluckbeschwerden Beginn und Verlauf notieren und die Hausärztin oder den Hausarzt aufsuchen. Ursachen wie Arzneimittel, Zähne und Schlucken abklären lassen; bei Bedarf Diätologie einbeziehen. Trinknahrung und Präparate nicht auf eigene Faust beginnen, sondern auf den Gesundheitszustand abstimmen.", source: nutrition),
        .init("living-options", "building.2", "Порівняйте житлові варіанти до переїзду", "Wohnformen vor dem Umzug vergleichen",
              "Якщо сходи або віддалені послуги ускладнюють життя, порівняйте доступне житло, Seniorenwohnung, betreutes/betreubares Wohnen і будинок догляду. Запитайте письмово, що входить в оренду та базову плату, які послуги оплачують окремо, чи є нічна допомога і як розривається договір. «Betreutes Wohnen» не означає автоматично цілодобовий догляд. Відвідайте місце й перевірте транспорт до лікаря та близьких.",
              "Wenn Stiegen oder entfernte Angebote den Alltag erschweren, barrierefreie Wohnung, Seniorenwohnung, betreutes/betreubares Wohnen und Pflegeheim vergleichen. Schriftlich nach Miete, Grundentgelt, Zusatzkosten, nächtlicher Hilfe und Kündigung fragen. „Betreutes Wohnen“ bedeutet nicht automatisch Pflege rund um die Uhr. Den Ort besuchen und Wege zu Arztpraxis und Angehörigen prüfen.", source: housing),
        .init("social-contact", "person.2", "Поверніть регулярні контакти", "Regelmäßige Kontakte aufbauen",
              "Оберіть один регулярний контакт, який людині до вподоби: зустріч у громаді, бібліотеці, старшому клубі чи спільну прогулянку. Заздалегідь уточніть доступність, мову, дорогу та вартість; попросіть когось піти разом уперше. Якщо самотність супроводжується тривалим пригніченням, порушенням сну або відмовою від їжі, зверніться до лікаря — спілкування не замінює лікування.",
              "Einen regelmäßigen, gewünschten Kontakt auswählen: Gemeindetreffen, Bibliothek, Seniorentreff oder gemeinsamer Spaziergang. Barrierefreiheit, Sprache, Anreise und Kosten vorab klären; für den ersten Besuch Begleitung organisieren. Bei anhaltender Niedergeschlagenheit, Schlafproblemen oder Nahrungsverweigerung ärztlich abklären lassen; Kontakte ersetzen keine Behandlung.", source: loneliness),
        .init("digital-confidence", "iphone", "Опануйте потрібне онлайн без поспіху", "Digitale Alltagswege in Ruhe lernen",
              "Для запису до лікаря, повідомлень близьким чи онлайн-послуг спочатку виберіть одну конкретну дію. На сторінці Digital Überall шукайте безкоштовний курс для початківців у своїй землі й уточнюйте мову, дату та спосіб запису; доступність місць змінюється. Паролі й коди підтвердження не передавайте людині, яка навчає, і залиште собі паперовий спосіб зв’язку.",
              "Für Arzttermine, Nachrichten an Angehörige oder Amtswege zuerst eine konkrete Tätigkeit wählen. Auf Digital Überall einen kostenlosen Einstiegskurs im Bundesland suchen und Sprache, Termin sowie Anmeldung prüfen; verfügbare Plätze ändern sich. Passwörter und Bestätigungscodes nicht an Helfende weitergeben und einen Kontaktweg auf Papier behalten.", source: digital)
    ]
}
